"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["2144"],{99580(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_cascata_remanejamento.ordem_nao_contigua","status":422,"titulo":"A sequ\xeancia de ordens de uma origem n\xe3o \xe9 cont\xedgua a partir de 1"},"descricao":{"codigo":"uniplus.selecao.configuracao_cascata_remanejamento.ordem_nao_contigua","requisitos":["UNI-REQ-0056"],"oQueAconteceu":["A fila de destinos de uma origem, ordenada por `ordem`, tem uma lacuna \u2014\\npor exemplo, ordens `1` e `3` sem o `2`. A fila precisa ser cont\xedgua a\\npartir de 1: se uma posi\xe7\xe3o da sequ\xeancia n\xe3o existe, o remanejamento n\xe3o\\nsabe o que tentar quando chega ali.","Roda na mesma passada por origem que\\n[`ordem_duplicada_na_origem`](/erros/uniplus.selecao.configuracao_cascata_remanejamento.ordem_duplicada_na_origem)\\ne\\n[`destino_duplicado`](/erros/uniplus.selecao.configuracao_cascata_remanejamento.destino_duplicado),\\ndepois de todos os itens de `destinos` j\xe1 terem sido constru\xeddos com\\nsucesso \u2014 a mesma condi\xe7\xe3o de alcan\xe7abilidade e o mesmo padr\xe3o de\\nacumula\xe7\xe3o (ADR-0125) das duas causas irm\xe3s se aplicam aqui. Como\\n`ordem_duplicada_na_origem`, tamb\xe9m para na primeira lacuna que encontrar\\ndentro de uma mesma origem, contribuindo no m\xe1ximo uma ocorr\xeancia por\\norigem \u2014 outras origens com lacunas pr\xf3prias contribuem cada uma com a\\nsua."],"comoResolver":["Revise a fila de destinos da origem apontada e renumere a sequ\xeancia\\ninteira a partir de 1, sem pular posi\xe7\xf5es."],"ondeAparece":["Defini\xe7\xe3o de cascata de remanejamento do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao cascata remanejamento"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);